function isPro(){try{if(window.RW_CINEMATIC_PREVIEW===true||sessionStorage.getItem('rw_cinematic_preview')==='1')return true;if(window.isPro===true||window.RW_PRO===true||window.proUnlocked===true)return true;if(localStorage.getItem('rwPro')==='1')return true;if(typeof window.rwIsPro==='function'&&window.rwIsPro())return true;if(typeof window.isPro==='function'&&window.isPro())return true;if(window.RW_USER?.isPro===true||window.RW?.user?.isPro===true)return true}catch(_){}return false}
function openUpgrade(){toast('Cinematic Journey is available with RoamWise Pro.');try{if(typeof window.openPay==='function')return window.openPay()}catch(_){}$('#heroProBtn')?.click()}
function formContext(){const tags=$$('#tagsContainer .tag.on').map(x=>x.dataset.v||x.textContent.trim()).filter(Boolean);const exact=$('#budgetExact')?.value?.trim();return{destination:text('#destInput',window._lastItin?.name||'Your destination')||window._lastItin?.name||'Your destination',origin:text('#origin','Your city'),month:selectedText('#month','Flexible dates'),duration:selectedText('#dur','Trip'),days:Math.max(1,parseInt($('#dur')?.value||window._lastItin?.days?.length||'7',10)||7),style:selectedText('#style','Traveler'),crowd:selectedText('#crowd','Balanced crowds'),transport:selectedText('#tmode','Mixed transport'),budget:exact?`${text('#budgetExactSym','')} ${exact}`.trim():text('#budgetDisplay','Flexible budget'),interests:tags}}
function flattenValue(value,depth=0){if(value==null||depth>2)return'';if(typeof value==='string'||typeof value==='number')return String(value);if(Array.isArray(value))return value.map(v=>flattenValue(v,depth+1)).filter(Boolean).join(' · ');if(typeof value==='object'){return Object.entries(value).filter(([k])=>!/^(id|lat|lng|latitude|longitude|image|photo|url)$/i.test(k)).map(([k,v])=>{const t=flattenValue(v,depth+1);return t?`${k.replace(/[_-]/g,' ')}: ${t}`:''}).filter(Boolean).join(' · ')}return''}
function cleanDayText(s){return String(s||'').replace(/\s+/g,' ').replace(/^Day\s*\d+\s*[:\-–—]?\s*/i,'').trim()}
function daysFromState(ctx){const itin=window._lastItin;if(!itin||!Array.isArray(itin.days)||!itin.days.length)return[];const name=String(itin.name||itin.destination||'').trim().toLowerCase();const dest=String(ctx.destination||'').trim().toLowerCase();if(name&&dest&&name!==dest&&!name.includes(dest)&&!dest.includes(name))return[];return itin.days.map((d,i)=>{const n=Number(d?.day||d?.n||d?.dayNumber||i+1)||i+1;const title=cleanDayText(d?.title||d?.name||d?.headline||d?.place||d?.location||`Day ${n}`)||`Day ${n}`;const source=flattenValue(d).replace(/\s+/g,' ').trim();return{n,title,body:source.slice(0,1800),source}}).filter(d=>d.source.length>20)}
function closestDayBlock(node,root){let el=node,best=null;while(el&&el!==root&&el!==document.body){const raw=(el.innerText||el.textContent||'').trim();if(raw.length>=80&&raw.length<=9000)best=el;if(/^(ARTICLE|SECTION)$/i.test(el.tagName)&&raw.length>=80)return el;if(el.matches?.('[data-day],.day,.itin-day,.itinerary-day,.result-card,.itin-card,.itinerary-card'))return el;el=el.parentElement}return best}
function daysFromDom(root){if(!root)return[];const markers=$$('h1,h2,h3,h4,h5,h6,strong,b,[data-day],[class*="day-title"],[class*="dayTitle"]',root).filter(el=>/\bDay\s*\d+\b/i.test((el.textContent||'').trim()));const byDay=new Map();for(const marker of markers){const mm=(marker.textContent||'').match(/\bDay\s*(\d+)\b/i);if(!mm)continue;const n=Number(mm[1]);const block=closestDayBlock(marker,root);if(!block)continue;const raw=(block.innerText||block.textContent||'').trim();if(raw.length<70)continue;const previous=byDay.get(n);if(!previous||raw.length<previous.raw.length)byDay.set(n,{marker,block,raw})}const out=[];for(const[n,item]of byDay.entries()){const first=(item.marker.textContent||'').trim();const title=cleanDayText(first).slice(0,120)||`Day ${n}`;const body=item.raw.replace(first,'').trim();out.push({n,title,body:body.slice(0,2200),source:item.raw})}if(out.length)return out.sort((a,b)=>a.n-b.n);const raw=(root.innerText||root.textContent||'').trim();if(!/\bDay\s*1\b/i.test(raw))return[];const chunks=raw.split(/(?=\bDay\s*\d+\b)/i).filter(x=>/^\s*Day\s*\d+/i.test(x));return chunks.slice(0,30).map((chunk,i)=>{const m=chunk.match(/^\s*Day\s*(\d+)\s*[:\-–—]?\s*([^\n|]{0,120})/i);const n=m?Number(m[1]):i+1;const title=cleanDayText(m?.[2]||`Day ${n}`);return{n,title,body:chunk.slice(0,2200),source:chunk.trim()}})}
function extractDays(root,ctx){const fromState=daysFromState(ctx);const days=fromState.length?fromState:daysFromDom(root);return days.filter(d=>d.n>0&&d.source.length>20).sort((a,b)=>a.n-b.n).slice(0,30)}
function hasValidClassic(){const results=$('#results');if(!results)return false;const ctx=formContext();const days=extractDays(results,ctx);return days.length>0&&((results.innerText||results.textContent||'').trim().length>120||daysFromState(ctx).length>0)}
function classicFingerprint(){const r=$('#results');const ctx=formContext();return`${ctx.destination}|${ctx.days}|${(r?.innerText||r?.textContent||'').trim().slice(0,1800)}`}
function ensureResultLauncher(){const results=$('#results');if(!results)return;const valid=hasValidClassic();let bar=$('#rwCineResultLauncher');if(!valid){bar?.remove();if(state.mode==='cinematic')setMode('classic',{silent:true});return}if(!bar){bar=document.createElement('div');bar.id='rwCineResultLauncher';bar.innerHTML=`<div class="rw-result-switch-copy"><span class="rw-result-switch-kicker">Journey view</span><strong>Choose how to experience this itinerary</strong><small>Classic keeps every original detail. Cinematic turns the same plan into an animated journey.</small></div><div class="rw-result-switch" role="group" aria-label="Itinerary experience"><button type="button" class="on" data-rw-mode="classic" aria-pressed="true">Classic</button><button type="button" data-rw-mode="cinematic" aria-pressed="false">✦ Cinematic <span>PRO</span></button></div>`;results.parentNode.insertBefore(bar,results);bar.addEventListener('click',e=>{const btn=e.target.closest('[data-rw-mode]');if(!btn)return;state.userChangedMode=true;setMode(btn.dataset.rwMode)})}syncLauncher()}
function syncLauncher(){$$('#rwCineResultLauncher [data-rw-mode]').forEach(btn=>{const on=btn.dataset.rwMode===state.mode;btn.classList.toggle('on',on);btn.setAttribute('aria-pressed',String(on))})}
function setMode(mode,opts={}){const results=$('#results');if(mode==='cinematic'){if(!isPro())return openUpgrade();if(!hasValidClassic()){if(!opts.silent)toast('Generate the Classic itinerary first; Cinematic will appear beside it automatically.');return false}const ok=renderCinematic();if(!ok){results?.classList.remove('rw-cine-classic-hidden');state.mode='classic';syncLauncher();return false}state.mode='cinematic';results?.classList.add('rw-cine-classic-hidden');syncLauncher();return true}state.mode='classic';results?.classList.remove('rw-cine-classic-hidden');$('#rwCinematicMount')?.remove();stopAudio();state.routePoints=[];state.mapLoaded=false;syncLauncher();if(!opts.silent&&results)results.scrollIntoView({behavior:'smooth',block:'start'});return true}
function safeDeriveStops(destination){if(typeof window.rwDeriveStops!=='function')return null;try{const it=window._lastItin;const name=String(it?.name||'').trim().toLowerCase();const dest=String(destination||'').trim().toLowerCase();const matches=!it||!name||name===dest||name.includes(dest)||dest.includes(name);if(it&&!matches){const saved=window._lastItin;window._lastItin=null;try{return window.rwDeriveStops(destination)}finally{window._lastItin=saved}}return window.rwDeriveStops(destination)}catch(_){return null}}
function derivePlace(day,ctx){const raw=`${day.title} ${day.source}`;const arrows=raw.split(/→|->|\bto\b/i).map(s=>s.trim()).filter(Boolean);if(arrows.length>1){const m=arrows[arrows.length-1].match(/^([A-Z][A-Za-zÀ-ÿ.'’\-]+(?:\s+[A-Z][A-Za-zÀ-ÿ.'’\-]+){0,3})/);if(m)return m[1]}const m=raw.match(/(?:arrive|drive|ride|train|flight|stay|overnight|explore|visit|at|in)\s+(?:at\s+|in\s+)?([A-Z][A-Za-zÀ-ÿ.'’\-]+(?:\s+[A-Z][A-Za-zÀ-ÿ.'’\-]+){0,3})/);return m?.[1]?.trim()||ctx.destination}
function buildRoute(days,ctx){const appStops=safeDeriveStops(ctx.destination);let route=Array.isArray(appStops)&&appStops.length?appStops.map((s,i)=>({day:Number(s.day||i+1),place:s.name||s.place||ctx.destination,title:s.note||''})):days.map(d=>({day:d.n,place:derivePlace(d,ctx),title:d.title}));route=route.filter(r=>r.place&&String(r.place).trim());const compact=[];route.forEach(r=>{const place=String(r.place).trim();const prev=compact[compact.length-1];if(!prev||prev.day!==r.day||prev.place.toLowerCase()!==place.toLowerCase())compact.push({...r,place})});return compact.length?compact:[{day:1,place:ctx.destination,title:ctx.destination}]}
function mediaTarget(){const saveData=!!navigator.connection?.saveData;const effective=String(navigator.connection?.effectiveType||'');if(saveData||/(^|-)2g$/.test(effective))return{w:1280,h:720,q:78};const pixels=Math.max(screen?.width||innerWidth||1920,innerWidth||1920)*Math.max(1,devicePixelRatio||1);if(pixels>=4200&&!/3g/.test(effective))return{w:3840,h:2160,q:88};return{w:2560,h:1440,q:84}}
function upgradePhoto(url){if(!url)return'';try{const u=new URL(url,location.href);if(u.hostname.includes('weserv.nl')){const src=decodeURIComponent(u.searchParams.get('url')||'');let original=src;const m=src.match(/^(.*\/wikipedia\/commons)\/thumb\/([^/]+\/[^/]+\/[^/]+)\/\d+px-[^/]+$/i);if(m)original=`${m[1]}/${m[2]}`;const t=mediaTarget();u.searchParams.set('url',original);u.searchParams.set('w',String(t.w));u.searchParams.set('h',String(t.h));u.searchParams.set('fit','cover');u.searchParams.set('q',String(t.q));u.searchParams.set('output','webp');return u.toString()}}catch(_){}return url}
function photoFor(place,destination){const photos=window.RW_PHOTOS_DATA||{};const candidates=[place,destination].filter(Boolean).map(x=>String(x).toLowerCase());let key=Object.keys(photos).find(k=>candidates.includes(k.toLowerCase()));if(!key)key=Object.keys(photos).find(k=>candidates.some(c=>c.includes(k.toLowerCase())||k.toLowerCase().includes(c)));return upgradePhoto(key?photos[key]:'')}
function themeFor(destination){const d=String(destination||'').toLowerCase();if(/kedarnath|badrinath|gangotri|yamunotri|char dham|rishikesh|varanasi|temple|pilgrim/.test(d))return'scarlet-pilgrim';if(/meghalaya|assam|tawang|arunachal|sikkim|nagaland|manipur|mizoram|tripura|darjeeling|northeast/.test(d))return'eastern-frontier';if(/everest|annapurna|kilimanjaro|inca|patagonia|mont blanc|markha|hampta|chadar|trek|expedition|base camp/.test(d))return'crimson-expedition';return'crimson-moon'}
function embers(){let out='';for(let i=0;i<22;i++)out+=`<i class="rw-ember" style="left:${(i*41)%100}%;--d:${6+(i%7)*.8}s;--delay:${-(i%11)*.67}s;--dx:${(i%2?1:-1)*(20+(i%5)*10)}px"></i>`;return out}
function heroHTML(ctx,media,theme){const interests=ctx.interests.slice(0,3).join(' · ')||'smart travel';const mediaStyle=media?`background-image:url('${esc(media)}')`:'';return`<header class="rw-cine-hero" data-rw-theme="${theme}"><div class="rw-cine-media" style="${mediaStyle}"></div><div class="rw-cine-moon" aria-hidden="true"></div><div class="rw-cine-embers" aria-hidden="true">${embers()}</div><div class="rw-cine-hero-copy"><div class="rw-cine-kicker">🥷 RoamWise · Cinematic Journey</div><h1 class="rw-cine-title">${esc(ctx.destination)}</h1><p class="rw-cine-subtitle">The same RoamWise plan, rebuilt as a visual journey — swipe through days, open local maps, inspect every detail, and follow the route without losing the Classic itinerary.</p><div class="rw-cine-meta"><span>${esc(ctx.month)}</span><span>${esc(ctx.duration)}</span><span>${esc(ctx.style)}</span><span>${esc(ctx.crowd)}</span><span>${esc(interests)}</span></div><div class="rw-cine-actions"><button class="rw-cine-action primary" data-rw-action="route">▶ Replay journey</button><button class="rw-cine-action" data-rw-action="live-map">⌖ Live map</button><button class="rw-cine-action" data-rw-action="audio">◉ Ambient</button><button class="rw-cine-action" data-rw-action="classic">Classic</button></div></div></header>`}
function shortPlace(s){return String(s||'').trim().split(/\s+/).slice(0,3).join(' ').slice(0,30)}
function routeFallbackSVG(route){const width=920,height=320,pad=58;const pts=route.map((r,i)=>({x:pad+(width-pad*2)*(route.length<=1?.5:i/(route.length-1)),y:height/2+Math.sin(i*1.55)*72+(i%2?26:-20),...r}));const path=pts.length>1?`M ${pts[0].x} ${pts[0].y} `+pts.slice(1).map((p,i)=>`C ${(pts[i].x+p.x)/2} ${pts[i].y}, ${(pts[i].x+p.x)/2} ${p.y}, ${p.x} ${p.y}`).join(' '):`M ${pts[0]?.x||width/2} ${pts[0]?.y||height/2} l 1 1`;return`<div class="rw-route-fallback"><svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Animated itinerary route"><path class="rw-path-ghost" d="${path}"/><path class="rw-path" d="${path}"/>${pts.map((p,i)=>`<g class="rw-route-pin"><circle cx="${p.x}" cy="${p.y}" r="7"/><text x="${p.x}" y="${p.y+(i%2?27:-19)}" text-anchor="middle">${esc(shortPlace(p.place))}</text></g>`).join('')}<g class="rw-svg-traveler" aria-hidden="true"><circle r="14"/><text x="0" y="7" text-anchor="middle">🥷</text><animateMotion class="rw-route-motion" dur="12s" repeatCount="indefinite" path="${path}" keyTimes="0;1" keySplines=".45 .05 .55 .95" calcMode="spline"/></g></svg></div>`}
function routeHTML(route){return`<section class="rw-cine-section rw-journey-cockpit" id="rwCineRoute"><div class="rw-cine-section-head"><div><div class="rw-cine-eyebrow">Journey cockpit</div><h2>See the whole trip without scrolling forever</h2></div><div class="rw-cine-small">Animated route · real map · elevation</div></div><div class="rw-cockpit-tabs" role="tablist"><button class="on" data-rw-cockpit="story">✦ Route story</button><button data-rw-cockpit="map">⌖ Live map</button><button data-rw-cockpit="elevation">⌁ Elevation</button></div><div class="rw-cockpit-panel on" data-rw-cockpit-panel="story"><div class="rw-route-map rw-route-story" id="rwCineRouteStory">${routeFallbackSVG(route)}</div><div class="rw-route-strip">${route.map(r=>`<button class="rw-route-stop" data-rw-focus-day="${r.day}"><span>Day ${r.day}</span><strong>${esc(r.place)}</strong><small data-rw-elev-place="${esc(r.place)}">Locating…</small></button>`).join('')}</div></div><div class="rw-cockpit-panel" data-rw-cockpit-panel="map"><div class="rw-live-map" id="rwCineLiveMap"><div class="rw-map-placeholder"><span>⌖</span><strong>Preparing the live map</strong><small>The map uses real geocoded route points and loads only when needed.</small></div></div></div><div class="rw-cockpit-panel" data-rw-cockpit-panel="elevation"><div class="rw-elev-wrap"><div class="rw-elev-bars" id="rwElevBars"><div class="rw-map-placeholder compact"><strong>Resolving elevation</strong><small>Real route elevations appear here when available.</small></div></div></div></div></section>`}
function keywordSentences(source,rx,fallback){const sentences=String(source||'').split(/(?<=[.!?])\s+|\n+/).map(x=>x.trim()).filter(Boolean).filter(x=>rx.test(x));return(sentences.slice(0,5).join(' ')||fallback).slice(0,1000)}
function transportIcon(ctx,source=''){const v=`${ctx.transport} ${source}`.toLowerCase();if(/flight|plane|airport/.test(v))return'✈';if(/train|rail|metro/.test(v))return'🚆';if(/ferry|boat/.test(v))return'⛴';if(/cycle|bike/.test(v))return'🚲';if(/walk|hike|trek/.test(v))return'🥾';if(/bus|coach/.test(v))return'🚌';return'🚙'}
function dayPlace(day,route,ctx){const stop=route.find(r=>Number(r.day)===Number(day.n));return stop?.place||derivePlace(day,ctx)||ctx.destination}
function dayHTML(day,ctx,route,idx){const place=dayPlace(day,route,ctx);const image=photoFor(place,ctx.destination);const stay=keywordSentences(day.source,/hotel|stay|hostel|resort|guesthouse|homestay|camp|overnight|room/i,'Open Stay & do to compare options around this day’s route.');const food=keywordSentences(day.source,/food|eat|breakfast|lunch|dinner|cafe|restaurant|dish|market|tea|coffee/i,'Explore local food near the day route and keep one meal window flexible.');const budget=keywordSentences(day.source,/₹|\$|€|£|¥|cost|budget|price|fare|fee|ticket|per person|night/i,`Trip target: ${ctx.budget}. Classic remains the source of truth for exact estimates.`);const move=keywordSentences(day.source,/drive|train|bus|flight|walk|cycle|ride|transfer|taxi|metro|ferry|km|hour|min/i,ctx.transport);const vehicle=transportIcon(ctx,move);const style=image?`style="--rw-day-image:url('${esc(image)}')"`:'';return`<article class="rw-day-card" data-rw-day="${day.n}" data-rw-carousel-index="${idx}" ${style}><div class="rw-day-photo" aria-hidden="true"></div><div class="rw-day-content"><div class="rw-day-heading"><div><span class="rw-day-num">Day ${day.n}</span><h3>${esc(day.title)}</h3><p>${esc(day.body.slice(0,620))}</p></div><div class="rw-day-weather" data-rw-weather-day="${day.n}"><span>◐</span><strong>Live context</strong><small>${esc(place)}</small></div></div><div class="rw-day-tabs" role="tablist"><button class="on" data-rw-panel="journey">↝ Journey</button><button data-rw-panel="details">☰ Full details</button><button data-rw-panel="stay">⌂ Stay</button><button data-rw-panel="food">◌ Food</button><button data-rw-panel="budget">₹ Budget</button><button data-rw-panel="map">⌖ Day map</button></div><div class="rw-day-panels"><div class="rw-day-panel on" data-rw-panel-body="journey"><div class="rw-transport-seq"><span>●</span><i></i><b>${vehicle}</b><span>◆</span></div><p>${esc(move)}</p></div><div class="rw-day-panel" data-rw-panel-body="details"><div class="rw-detail-scroll">${esc(day.source)}</div></div><div class="rw-day-panel" data-rw-panel-body="stay"><p>${esc(stay)}</p><button class="rw-tool-btn" data-rw-action="stay">Open Stay & do</button></div><div class="rw-day-panel" data-rw-panel-body="food"><p>${esc(food)}</p><button class="rw-tool-btn" data-rw-action="near">Find food near me</button></div><div class="rw-day-panel" data-rw-panel-body="budget"><p>${esc(budget)}</p><button class="rw-tool-btn" data-rw-action="money">Open money tools</button></div><div class="rw-day-panel" data-rw-panel-body="map"><div class="rw-mini-map" data-rw-mini-map="${day.n}"><div class="rw-map-placeholder compact"><span>⌖</span><strong>Day ${day.n} live map</strong><small>Tap this tab to load the local map.</small></div></div></div></div></div></article>`}
function carouselHTML(days,ctx,route){return`<section class="rw-cine-section rw-days-section"><div class="rw-cine-section-head"><div><div class="rw-cine-eyebrow">Daily dossier</div><h2>Swipe the journey, one day at a time</h2></div><div class="rw-carousel-count"><strong id="rwCarouselCurrent">1</strong><span>/ ${days.length}</span></div></div><div class="rw-day-rail" aria-label="Jump to a day">${days.map((d,i)=>`<button class="${i===0?'on':''}" data-rw-jump-day="${i}">D${d.n}</button>`).join('')}</div><div class="rw-day-carousel-shell"><button class="rw-carousel-arrow prev" data-rw-carousel-action="prev" aria-label="Previous day">‹</button><div class="rw-day-carousel" id="rwDayCarousel" tabindex="0">${days.map((d,i)=>dayHTML(d,ctx,route,i)).join('')}</div><button class="rw-carousel-arrow next" data-rw-carousel-action="next" aria-label="Next day">›</button></div><div class="rw-swipe-hint">← swipe / scroll horizontally →</div></section>`}
function toolsHTML(ctx){return`<section class="rw-cine-section rw-field-console"><div class="rw-cine-section-head"><div><div class="rw-cine-eyebrow">Field console</div><h2>Useful tools, not another long page</h2></div></div><div class="rw-tool-rail"><button class="rw-tool-card" data-rw-action="stay"><span>🏨</span><strong>Stay intelligence</strong><small>Hotels, homestays and experiences around the route.</small></button><button class="rw-tool-card" data-rw-action="money"><span>💸</span><strong>Budget cockpit</strong><small>${esc(ctx.budget)} target with buffers and money tools.</small></button><button class="rw-tool-card" data-rw-action="near"><span>📍</span><strong>Arrival mode</strong><small>Food, essentials and nearby context when you are on the ground.</small></button><button class="rw-tool-card" data-rw-action="live-map"><span>🗺️</span><strong>Live route map</strong><small>Jump straight back to the real geographic route.</small></button></div></section>`}
