function ensureInlineButton(){$('#rwCineResultLauncher')?.remove();const old=$('#rwCineInlineBtn');if(!hasClassic()){old?.remove();if(state.mode==='cinematic')setMode('classic',true);return}if(old)return syncInlineButton();const spot=findClassicActionHost();if(!spot)return;const b=document.createElement('button');b.id='rwCineInlineBtn';b.type='button';b.className='tact rw-cine-inline-btn';b.innerHTML='<span class="rw-cine-spark">✦</span><span>Cinematic</span><small>PRO</small>';b.addEventListener('click',()=>setMode('cinematic'));if(spot.before&&spot.before.parentElement===spot.host)spot.host.insertBefore(b,spot.before);else spot.host.appendChild(b);syncInlineButton()}
function syncInlineButton(){const b=$('#rwCineInlineBtn');if(!b)return;b.classList.toggle('on',state.mode==='cinematic');b.setAttribute('aria-pressed',String(state.mode==='cinematic'))}
function destroyMaps(){state.maps.forEach(m=>{try{m.destroy()}catch(_){}});state.maps=[]}
function setMode(mode,silent){const r=$('#results');if(mode==='cinematic'){if(!isPro())return openUpgrade();if(!hasClassic()){if(!silent)toast('Generate the Classic itinerary first.');return false}if(!renderCinematic()){if(!silent)toast('Classic itinerary could not be read yet.');return false}state.mode='cinematic';r?.classList.add('rw-cine-classic-hidden');syncInlineButton();return true}r?.classList.remove('rw-cine-classic-hidden');$('#rwCinematicMount')?.remove();destroyMaps();state.mode='classic';state.renderToken++;state.route=[];state.road=null;state.dayRoutes={};syncInlineButton();if(!silent)r?.scrollIntoView({behavior:'smooth',block:'start'});return true}
function placeFromTitle(t){const a=clean(t).split(/→|->|\bto\b/i).filter(Boolean);let x=a[a.length-1]||t;x=x.replace(/^(bonus exploration|free day|buffer day|rest day)$/i,'');return clean(x)}
