async function appGeocode(q){if(!q)return null;const k=norm(q);if(state.geoCache[k])return state.geoCache[k];try{if(typeof window.gcode==='function'){const g=await timeout(window.gcode(q),4300);if(g&&Number.isFinite(+g.lat)&&Number.isFinite(+g.lon)){const o={lat:+g.lat,lng:+g.lon,name:g.name||q,elevation:Number(g.elevation||0)||null,source:'roamwise-geocoder'};state.geoCache[k]=o;return o}}}catch(_){}try{const c=new AbortController(),tm=setTimeout(()=>c.abort(),4300),u='https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=1&language=en&format=json',r=await fetch(u,{cache:'force-cache',signal:c.signal});clearTimeout(tm);if(r.ok){const g=(await r.json())?.results?.[0];if(g){const o={lat:+g.latitude,lng:+g.longitude,name:g.name||q,elevation:Number(g.elevation||0)||null,source:'open-meteo'};state.geoCache[k]=o;return o}}}catch(_){}return null}
