async function routeRoad(points,profile='driving'){const valid=points.filter(p=>Number.isFinite(+p.lat)&&Number.isFinite(+p.lng));if(valid.length<2)return fallbackRoute(valid,profile);const chunks=[];for(let i=0;i<valid.length-1;i+=18){const part=valid.slice(i,Math.min(i+19,valid.length));if(part.length>1)chunks.push(part)}let geometry=[],distance=0,duration=0,source='road',legs=[];for(const part of chunks){const rt=await osrmChunk(part,profile);if(!rt){source='estimate';const f=fallbackRoute(part,profile);geometry.push(...f.geometry.slice(geometry.length?1:0));distance+=f.distance;duration+=f.duration;continue}geometry.push(...rt.geometry.slice(geometry.length?1:0));distance+=rt.distance;duration+=rt.duration;legs.push(...(rt.legs||[]))}return{geometry,distance,duration,source,legs}}
function fmtDistance(m){if(!Number.isFinite(+m))return'';return m<1000?Math.round(m)+' m':(m/1000).toFixed(m<10000?1:0)+' km'}
function fmtDuration(sec){if(!Number.isFinite(+sec))return'';const m=Math.round(sec/60);if(m<60)return m+' min';const h=Math.floor(m/60),mm=m%60;return h+'h'+(mm?' '+mm+'m':'')}
