function theme(ctx){const d=norm(ctx.destination);if(/kedarnath|badrinath|varanasi|pilgrim|temple|rishikesh|char dham/.test(d))return'pilgrim';if(/everest|annapurna|kilimanjaro|trek|expedition|base camp|chadar|hampta|markha/.test(d))return'expedition';if(/meghalaya|tawang|sikkim|northeast|arunachal|nagaland/.test(d))return'frontier';if(/goa|bali|maldives|island|coast|beach|andaman|lakshadweep/.test(d))return'coast';return'crimson'}
