function paintMainMap(points,road,ctx){const host=$('#rwV5LiveMap'),status=$('#rwV5MapStatus'),stats=$('#rwV5RouteStats');if(!host)return;const v=points.filter(p=>p.geo),mapPts=v.map(p=>({lat:p.geo.lat,lng:p.geo.lng,label:'D'+p.day,name:p.name}));if(!mapPts.length){host.innerHTML='<div class="rw-v5-map-loading compact"><b>Route points unavailable</b><small>Your itinerary is still readable; open Classic to edit the stops.</small></div>';if(status)status.textContent='Map unavailable';return}const m=new SlippyMap(host,{id:'main',points:mapPts,geometry:road?.geometry||mapPts.map(p=>[p.lng,p.lat]),duration:Math.max(10,Math.min(32,(road?.duration||9000)/900))});state.maps.push(m);if(status)status.textContent=(road?.source==='road'?'Road route mapped':'Approximate route')+' · '+mapPts.length+' days';if(stats)stats.innerHTML=`<span><b>${fmtDistance(road?.distance)}</b> route</span><span><b>${fmtDuration(road?.duration)}</b> movement</span><span><b>${mapPts.length}</b> mapped days</span>`;const ext=$('[data-rw-open-external-map]');if(ext)ext.onclick=()=>{const p=mapPts[Math.floor(mapPts.length/2)];window.open('https://www.openstreetmap.org/?mlat='+p.lat+'&mlon='+p.lng+'#map=8/'+p.lat+'/'+p.lng,'_blank','noopener')}}
